import sys

def longest_palindromic_prefix(s):
    n = len(s)
    rev_s = s[::-1]
    combined = s + '#' + rev_s
    lps = [0] * len(combined)
    for i in range(1, len(combined)):
        j = lps[i - 1]
        while j > 0 and combined[i] != combined[j]:
            j = lps[j - 1]
        if combined[i] == combined[j]:
            j += 1
        lps[i] = j
    return s[:lps[-1]]

def longest_palindromic_suffix(s):
    return longest_palindromic_prefix(s[::-1])[::-1]

def main():
    import sys
    s = sys.stdin.read().strip()
    lps = longest_palindromic_prefix(s)
    lss = longest_palindromic_suffix(s)
    omeric = lss + lps
    prefix_freq = {}
    for i in range(1, len(omeric) + 1):
        prefix = omeric[:i]
        prefix_freq[prefix] = prefix_freq.get(prefix, 0) + 1
    print(omeric)
    print(' '.join(str(prefix_freq[omeric[:i]]) for i in range(1, len(omeric) + 1)))

if __name__ == "__main__":
    main()
